const SHELL_CACHE = 'guru-shell-' + VERSION;
const RUNTIME_CACHE = 'guru-runtime-' + VERSION;
const SHARE_CACHE = 'guru-share-inbox-v1'; // must match src/connectors/device.js; not versioned: shared files must survive updates
const OWN_CACHES = [SHELL_CACHE, RUNTIME_CACHE, SHARE_CACHE];

// Hosts that carry credentials or LLM/API traffic: never intercepted, never cached.
const NEVER_CACHE_HOSTS = [
  'api.anthropic.com', 'api.openai.com', 'generativelanguage.googleapis.com',
  'accounts.google.com', 'oauth2.googleapis.com', 'www.googleapis.com', 'googleapis.com',
  'apis.google.com', 'docs.googleapis.com', 'sheets.googleapis.com', 'slides.googleapis.com',
  'api.github.com', 'github.com', 'raw.githubusercontent.com', 'gsi.client-channel.google.com',
];
const API_PATH = /\/(api|auth|oauth|v1|v1beta|proxy)(\/|$)/;

const OFFLINE_HTML = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guru offline</title><style>body{font:16px/1.5 system-ui,"Noto Sans Devanagari",sans-serif;margin:0;padding:32px 16px;background:#101418;color:#e8edf2}main{max-width:32rem;margin:auto}h1{font-size:1.4rem}</style></head><body><main><h1>Guru is offline / गुरु ऑफ़लाइन है</h1><p>This page is not saved on the device yet. Reconnect once and open Guru; after that it works offline.</p><p>यह पेज अभी डिवाइस में सेव नहीं है। एक बार इंटरनेट से जुड़कर Guru खोलें, फिर यह ऑफ़लाइन भी चलेगा।</p></main></body></html>`;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL_CACHE);
    // Tolerant precache: one missing file must not block install.
    await Promise.all(PRECACHE.map(async (u) => {
      try {
        const res = await fetch(new Request(u, { cache: 'reload' }));
        if (res.ok) await cache.put(new Request(u), res);
      } catch (_) { /* offline during install: skip */ }
    }));
    // Prompt flow: do NOT skipWaiting here; page asks via SKIP_WAITING message.
    const list = await self.clients.matchAll({ includeUncontrolled: true });
    for (const c of list) c.postMessage({ type: 'sw:waiting', version: VERSION });
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter((n) => n.startsWith('guru-') && !OWN_CACHES.includes(n)).map((n) => caches.delete(n)));
    if (self.registration.navigationPreload) { try { await self.registration.navigationPreload.disable(); } catch (_) {} }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const d = event.data || {};
  if (d.type === 'SKIP_WAITING') self.skipWaiting();
  else if (d.type === 'GET_VERSION' && event.source) event.source.postMessage({ type: 'sw:version', version: VERSION });
  else if (d.type === 'CLEAR_SHARE') event.waitUntil(caches.delete(SHARE_CACHE));
});

function isNeverCache(url) {
  const h = url.hostname;
  if (NEVER_CACHE_HOSTS.some((x) => h === x || h.endsWith('.' + x))) return true;
  if (url.origin !== self.location.origin) return true; // cross-origin: leave to network (CORS proxies, CDNs, APIs)
  return API_PATH.test(url.pathname);
}

const SHARE_MAX_FILES = 10, SHARE_MAX_BYTES = 25 * 1024 * 1024;
async function handleShare(request) {
  const origin = request.headers.get('origin');
  if (origin && origin !== self.location.origin && request.headers.get('sec-fetch-site') === 'cross-site' && request.headers.get('sec-fetch-dest') !== 'document') return new Response('forbidden', { status: 403 });
  const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  try {
    const form = await request.formData();
    const cache = await caches.open(SHARE_CACHE);
    const meta = { id, ts: Date.now(), title: String(form.get('title') || ''), text: String(form.get('text') || ''), url: String(form.get('url') || ''), files: [] };
    const base = self.location.origin + '/__share__/' + encodeURIComponent(id) + '/';
    let i = 0;
    for (const f of form.getAll('files')) {
      if (typeof f === 'string') continue;
      if (i >= SHARE_MAX_FILES || f.size > SHARE_MAX_BYTES) continue;
      const type = f.type || 'application/octet-stream';
      await cache.put(new Request(base + 'file/' + i), new Response(f, {
        headers: { 'Content-Type': type, 'X-Filename': encodeURIComponent(f.name || 'file-' + i) },
      }));
      meta.files.push({ name: f.name || 'file-' + i, type, size: f.size });
      i++;
    }
    await cache.put(new Request(base + 'meta.json'), new Response(JSON.stringify(meta), { headers: { 'Content-Type': 'application/json' } }));
    const list = await self.clients.matchAll({ includeUncontrolled: true });
    for (const c of list) c.postMessage({ type: 'guru-share', id });
  } catch (e) {
    return Response.redirect(new URL('./?share-error=1', self.registration.scope).href, 303);
  }
  return Response.redirect(new URL('./?share=' + id, self.registration.scope).href, 303);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);

  if (req.method === 'POST' && url.origin === self.location.origin && /\/share-target\/?$/.test(url.pathname)) {
    event.respondWith(handleShare(req));
    return;
  }
  if (req.method !== 'GET' || !/^https?:$/.test(url.protocol) || isNeverCache(url)) return;
  if (req.headers.has('range')) return;

  // Navigations: network-first, fall back to cached shell, then offline page.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const res = await fetch(req);
        if (res.ok) { const c = await caches.open(SHELL_CACHE); c.put(new Request('./index.html'), res.clone()).catch(() => {}); }
        return res;
      } catch (_) {
        const c = await caches.open(SHELL_CACHE);
        return (await c.match('./index.html')) || (await c.match('./')) ||
          new Response(OFFLINE_HTML, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
      }
    })());
    return;
  }

  // Precached shell asset: cache-first (version-pinned). Everything else same-origin: stale-while-revalidate.
  event.respondWith((async () => {
    const shell = await caches.open(SHELL_CACHE);
    const inShell = await shell.match(req, { ignoreSearch: true });
    const isSrc = /\/(src|data)\//.test(url.pathname);
    if (inShell && !isSrc) return inShell;
    const rt = await caches.open(RUNTIME_CACHE);
    const cached = inShell || (await rt.match(req));
    const fetching = fetch(req).then((res) => {
      if (res && res.ok && res.type === 'basic') rt.put(req, res.clone()).catch(() => {});
      return res;
    });
    if (cached) { fetching.catch(() => {}); return cached; }
    try { return await fetching; }
    catch (_) { return new Response('', { status: 504, statusText: 'offline' }); }
  })());
});
